import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, fract, sin, dot, float, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const colors =
    (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const bg = colors.background || '#0b0b10';
  const surface = colors.surface || '#14141a';
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';

  const root = new Group();
  root.name = 'editorial-oversized-type';

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // Backdrop stage (fills frame behind the plate) — engineered gradient
  // ---------------------------------------------------------------
  const gradientNode = (grainAmp) => {
    const g = mix(color(bg), color(surface), uv().y.clamp(0.0, 1.0));
    const n = fract(
      sin(dot(uv().mul(vec2(512.0, 320.0)), vec2(12.9898, 78.233))).mul(43758.5453)
    );
    return g.add(vec3(n.sub(0.5).mul(grainAmp)));
  };

  const backdropGeo = new PlaneGeometry(7.4, 6.2);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientNode(0.015);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // Editorial plate 7 x 5.5 at z=0 with gradient + 1.5% monochrome grain
  // ---------------------------------------------------------------
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshBasicNodeMaterial();
  plateMat.colorNode = gradientNode(0.03);
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---------------------------------------------------------------
  // Text content (verbatim from spec)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);

  const kickerItem = byRole('kicker')[0];
  const heroItems = byRole('hero');
  const bodyItem = byRole('body')[0];
  const captionItem = byRole('caption')[0];

  const LEFT_X = -3.1;
  const TEXT_Z = 0.05;

  // Each block is a Group so we can animate position + opacity uniformly.
  const blocks = [];

  const collectMaterials = (obj) => {
    const mats = [];
    obj.traverse((child) => {
      if (child.material) {
        const list = Array.isArray(child.material) ? child.material : [child.material];
        for (const m of list) {
          m.transparent = true;
          mats.push(m);
        }
      }
    });
    return mats;
  };

  const makeBlock = (textObj, x, y, z) => {
    const g = new Group();
    g.add(textObj);
    g.position.set(x, y, z);
    root.add(g);
    const mats = collectMaterials(textObj);
    blocks.push({ group: g, mats, targetY: y });
    return g;
  };

  // Kicker — JetBrains Mono 700, uppercase, tracking 0.12em
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(String(kickerItem.text), {
      fontSize: kickerItem.typography?.fontSize ?? 18,
      color: paper,
      align: 'left',
      letterSpacingPx: Math.round((kickerItem.typography?.fontSize ?? 18) * 0.12),
    });
    makeBlock(kicker, LEFT_X, 1.7, TEXT_Z);
  }

  // Hero — two stacked lines, Lora 600, tight tracking, letterpress shadow duplicate
  const heroYs = [0.9, 0.25];
  heroItems.forEach((item, i) => {
    const fs = item.typography?.fontSize ?? 124;
    const y = heroYs[i] ?? 0.25 - i * 0.65;

    // Letterpress shadow edge 0.02 units behind in ink
    const shadow = ctx.fontAtlas.createText(String(item.text), {
      fontSize: fs,
      color: ink,
      align: 'left',
      letterSpacingPx: Math.round(fs * -0.015),
    });
    shadow.position.set(0.015, -0.015, -0.02);

    const hero = ctx.fontAtlas.createText(String(item.text), {
      fontSize: fs,
      color: paper,
      align: 'left',
      letterSpacingPx: Math.round(fs * -0.015),
    });

    const wrap = new Group();
    wrap.add(shadow);
    wrap.add(hero);
    makeBlock(wrap, LEFT_X, y, TEXT_Z);
  });

  // Accent underline rule — 2.2 x 0.05, emissive-graded accent
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color(accent).mul(1.2); // brightest element on stage
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(LEFT_X + 1.1, -0.15, TEXT_Z);
  rule.scale.x = 0;
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // Body — max width 4.5 units. Scale: 124px hero == 0.62 units => 200px/unit.
  if (bodyItem) {
    const body = ctx.fontAtlas.createText(String(bodyItem.text), {
      fontSize: bodyItem.typography?.fontSize ?? 26,
      color: paper,
      align: 'left',
      maxWidthPx: Math.round(4.5 * 200),
    });
    makeBlock(body, LEFT_X, -0.8, TEXT_Z);
  }

  // Caption — mono, tracking 0.08em
  if (captionItem) {
    const caption = ctx.fontAtlas.createText(String(captionItem.text), {
      fontSize: captionItem.typography?.fontSize ?? 18,
      color: paper,
      align: 'left',
      letterSpacingPx: Math.round((captionItem.typography?.fontSize ?? 18) * 0.08),
    });
    makeBlock(caption, LEFT_X, -1.9, TEXT_Z);
  }

  // ---------------------------------------------------------------
  // Entrance: rise-in per block top-to-bottom, 700ms, 80ms stagger;
  // rule draws scaleX 0 -> 1 over 500ms after the hero lands.
  // ---------------------------------------------------------------
  const tl = gsap.timeline({ defaults: { overwrite: 'auto' } });
  timelines.push(tl);

  blocks.forEach((block, i) => {
    const at = i * 0.08;
    block.group.position.y = block.targetY + 0.4;
    tl.to(
      block.group.position,
      { y: block.targetY, duration: 0.7, ease: 'power3.out' },
      at
    );
    for (const m of block.mats) {
      m.opacity = 0;
      tl.to(m, { opacity: 1, duration: 0.7, ease: 'power2.out' }, at);
    }
  });

  // Hero lands: blocks[1] and [2] are hero lines (after kicker). Rule after last hero.
  const heroLandTime = (Math.min(blocks.length - 1, 2)) * 0.08 + 0.7;
  tl.to(
    rule.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    heroLandTime
  );

  // Idle: single slow breathing on the rule (<= 2%)
  const idle = gsap.to(rule.scale, {
    y: 1.02,
    duration: 2.4,
    yoyo: true,
    repeat: -1,
    ease: 'sine.inOut',
    delay: heroLandTime + 0.5,
  });
  timelines.push(idle);

  // ---------------------------------------------------------------
  // Handlers + cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    root.traverse((child) => {
      if (child.geometry && typeof child.geometry.dispose === 'function') {
        child.geometry.dispose();
      }
      if (child.material) {
        const list = Array.isArray(child.material) ? child.material : [child.material];
        for (const m of list) {
          if (m && typeof m.dispose === 'function') m.dispose();
        }
      }
    });
  };

  return root;
}
